          knowledgeSources: [{"title":"LangChain：检索与 RAG","url":"https://docs.langchain.com/oss/python/deepagents/retrieval"}],
          steps: ['新建 retrieval.py，导入上一课的 load_documents，加入示例函数。', '分别用 Git、文档、Skill 搜索，逐项标出结果是否能支持对应问题。', '用“存档”与“Git”比较结果；记录关键词局限，暂不把“未找到”写成确定没有答案。'],
          example: { label: 'retrieval.py', text: 'from documents import load_documents\n\ndef search_documents(keyword, limit=3):\n    keyword = keyword.strip()\n    if not keyword:\n        return []\n    hits = [d for d in load_documents() if keyword in d["text"]]\n    return hits[:limit]\n\nif __name__ == "__main__":\n    print(search_documents(input("关键词：")))' },
