            "text": "import os\nfrom langchain.agents import create_agent\nfrom langchain.tools import tool\nfrom tools_basic import list_documents\nfrom retrieval import search_documents\n\nprovider = os.environ[\"MODEL_PROVIDER\"].strip().lower()\nsettings = {\n    \"model\": os.environ[\"MODEL_NAME\"],\n    \"api_key\": os.environ[\"MODEL_API_KEY\"],\n    \"base_url\": os.environ[\"MODEL_BASE_URL\"],\n}\nif provider == \"deepseek\":\n    from langchain_deepseek import ChatDeepSeek\n    model = ChatDeepSeek(\n        **settings, extra_body={\"thinking\": {\"type\": \"disabled\"}}\n    )\nelif provider == \"openai\":\n    from langchain_openai import ChatOpenAI\n    model = ChatOpenAI(**settings, use_responses_api=False)\nelse:\n    raise ValueError(\"MODEL_PROVIDER 请填 deepseek 或 openai\")\n\n@tool\ndef list_files() -> list[str]:\n    \"\"\"列出当前可查询的资料文件名。\"\"\"\n    return list_documents()\n\n@tool\ndef search_files(keyword: str) -> list[dict]:\n    \"\"\"用原文关键词查找段落，返回文件名、段号和文字。\"\"\"\n    return search_documents(keyword)\n\nagent = create_agent(\n    model=model,\n    tools=[list_files, search_files],\n    system_prompt=\"查询资料必须使用工具；只按工具返回回答并引用文件和段号。没找到要说明，不编造。\",\n)\nresult = agent.invoke({\"messages\": [{\"role\": \"user\", \"content\": input(\"问题：\")}]})\nfor message in result[\"messages\"]:\n    print(message)\n# 检查真实 tool_calls 与 ToolMessage；分享前移除私人原文。"
