          knowledgeSources: [{"title":"Python：官方教程","url":"https://docs.python.org/zh-cn/3/tutorial/index.html"},{"title":"Git：版本状态与提交","url":"https://git-scm.com/book/zh/v2/Git-%E5%9F%BA%E7%A1%80-%E8%AE%B0%E5%BD%95%E6%AF%8F%E6%AC%A1%E6%9B%B4%E6%96%B0%E5%88%B0%E4%BB%93%E5%BA%93"}],
